package com.bank.evensum;

import java.util.logging.*;

public class EvenSumDemo {
    private static final Logger log = Logger.getLogger("EvenSum");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        EvenSumService service = new EvenSumService();
        log.info(() -> "Sum of evens 1..100 = " + service.sumEvens(1, 100)); // 2550
    }
}

// ─── Would be in service/EvenSumService.java ───
class EvenSumService {
    int sumEvens(int from, int to) {
        return java.util.stream.IntStream.rangeClosed(from, to)  // inclusive range
            .filter(n -> n % 2 == 0)                              // keep evens
            .sum();                                               // total
    }
}
